select 'maintenance', 'European Technical LLC', 'European Technical LLC', 'الشارقة', 'Sharjah Media City (Shams)', '+971 58 544 1160', 'https://europeantechnical.ae', 2025, 'شركة صيانة منزلية تأسست 2025 في مدينة الشارقة للإعلام وتخدم دبي والشارقة.', 'https://europeantechnical.ae/about', 'تأسست الشركة عام 2025 ومقرها مدينة الشارقة للإعلام (شمس)، وتخدم دبي والشارقة. تقدم أكثر من 65 خدمة منها التكييف والسباكة والكهرباء والنجارة والدهان وإصلاح الأجهزة وتركيب الكاميرات، إضافة إلى عقود الصيانة السنوية.', null, 'info@europeantechnical.ae', 'مدينة الشارقة للإعلام (شمس)، الشارقة، الإمارات', null, array['خدمات التكييف', 'السباكة والكهرباء', 'النجارة والدهان', 'إصلاح الأجهزة', 'عقود الصيانة السنوية']::text[], 'أكثر من 50 فنياً بعقود رواتب، تلقى كثير منهم تدريباً أو مؤهلات أوروبية.', true
where not exists (select 1 from public.service_providers where category = 'maintenance' and emirate = 'الشارقة' and lower(coalesce(name_en, name_ar)) = lower('European Technical LLC'));
