select 'maintenance', 'Al Mubashir Mechanical Contracting LLC', 'Al Mubashir Mechanical Contracting LLC', 'أم القيوين', 'Al Ittihad Road', '+971 55 134 4023', 'https://almubashir.net', null, 'مقاول تكييف وأنظمة كهروميكانيكية مقره أم القيوين يقدم صيانة التكييف والكهرباء والسباكة.', 'https://almubashir.net/', 'مقاول تكييف وأنظمة كهروميكانيكية يذكر أنه يعمل منذ 2006، ومقره الرئيسي في أم القيوين مع تركيز على دبي. يقدم صيانة وتركيب المكيفات والتشيلرات، والكهرباء والسباكة، وعقود الصيانة، وأعمال التجديد والنجارة والعزل المائي.', 'https://almubashir.net/_next/image/?url=%2Flogo-brand.png&w=640&q=75', 'almubashiracinstallation@gmail.com', 'مكتب 802، مركز الشموخ للأعمال، شارع الاتحاد، ص.ب 7332، أم القيوين', null, array['تمديد عزل خطوط المياه المبردة لوحدات FCU في دبي', 'تركيب مولد 450 كيلوفولت أمبير', 'استبدال كسوة الدكتات في دبا الفجيرة', 'تجديد فيلا (دهان وكهرباء وأعمال مدنية)']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'maintenance' and emirate = 'أم القيوين' and lower(coalesce(name_en, name_ar)) = lower('Al Mubashir Mechanical Contracting LLC'));
