select 'property_mgmt', 'Allsopp & Allsopp', 'Allsopp & Allsopp', 'دبي', 'موتور سيتي', '+971 4 429 4444', 'https://www.allsoppandallsopp.com', 2008, 'وكالة عقارية في دبي تقدم خدمات إدارة العقارات للملاك من تحصيل الإيجار إلى إدارة الصيانة.', 'https://www.allsoppandallsopp.com/dubai/landlords/property-management-services-dubai', 'تأسست الشركة عام 2008 وتقدم باقتين لإدارة العقارات: قياسية وممتازة. تشمل الخدمات تسليم المفاتيح وتحصيل الإيجار وتجديد العقود وتسجيل إيجاري وإدارة صيانة المستأجر، وتضيف الباقة الممتازة المحاسبة المالية وحل النزاعات والشيكات المرتجعة. تذكر الشركة أنها خاضعة لمؤسسة التنظيم العقاري (ريرا) برقم مكتب 1815.', 'https://www.allsoppandallsopp.com/images/AandA_Logo.svg', null, 'الطوابق 24 و30 و36، برج كونترول تاور، موتور سيتي، دبي، ص.ب 55720', null, array['تحصيل الإيجار', 'تجديد عقود الإيجار', 'تسجيل إيجاري', 'إدارة صيانة المستأجرين', 'فحص المستأجرين']::text[], 'يضم فريق دبي مئات من خبراء العقارات المدربين والخاضعين للتنظيم بحسب الموقع.', true
where not exists (select 1 from public.service_providers where category = 'property_mgmt' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Allsopp & Allsopp'));
