select 'property_mgmt', 'Espace Real Estate', 'Espace Real Estate', 'دبي', null, '+971 4 306 9999', 'https://www.espace.ae', 2009, 'وكالة عقارية في دبي تقدم إدارة العقارات من الصيانة العامة إلى إدارة المحافظ.', 'https://www.espace.ae/property-management-dubai', 'تأسست Espace عام 2009 وتقدم خدمات إدارة عقارات مفصلة تشمل التقييم وإرشاد الملاك وتسليم العقار والصيانة والمعاينات وجرد المحتويات والخدمات الإلكترونية. يذكر الموقع أن مديري العقارات لديها مؤهلون من ريرا.', 'https://www.espace.ae/img/espace-logo.svg', null, null, null, array['تقييم العقارات', 'تسليم العقار', 'الصيانة والمعاينات', 'التحقق من الجرد', 'الخدمات الإلكترونية']::text[], 'يذكر الموقع 270 موظفًا ومديري عقارات مؤهلين من ريرا.', true
where not exists (select 1 from public.service_providers where category = 'property_mgmt' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Espace Real Estate'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'property_mgmt', 'Metropolitan Premium Properties', 'Metropolitan Premium Properties', 'دبي', 'مدينة دبي للإنترنت', '+971 4 428 6151', 'https://metropolitan.realestate', 2008, 'شركة عقارية في دبي تقدم إدارة العقارات للملاك من التسعير والتسويق إلى تحصيل الإيجار وإيجاري.', 'https://metropolitan.realestate/services/property-management/', 'تأسست الشركة عام 2008 وتقدم خدمة إدارة العقارات بنسبة من الإيجار الشهري أو رسم شهري ثابت. تشمل الخدمة تحديد الإيجار والإصلاحات والتنظيف والتسويق وفحص المستأجرين وتسجيل إيجاري وتحصيل الإيجار والتجديد ومعاينات الدخول والخروج، مع تطبيق للملاك للتقارير المالية.', null, null, 'الطوابق 36-38، برج السلام تيكوم، مدينة دبي للإنترنت، دبي', null, array['تحديد قيمة الإيجار', 'فحص المستأجرين', 'تسجيل إيجاري', 'تحصيل الإيجار', 'تطبيق للملاك']::text[], 'مديرة إدارة العقارات: آيكو دوريمخان؛ ويذكر الموقع 250 وكيلًا.', true
where not exists (select 1 from public.service_providers where category = 'property_mgmt' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Metropolitan Premium Properties'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'property_mgmt', 'تنامي العقارية', 'Tanami Properties', 'دبي', 'دبي مارينا', '+971 4 248 3400', 'https://www.tanamiproperties.ae', null, 'شركة في دبي تدير أبراجًا سكنية وتجارية في دبي والشارقة وعجمان نيابة عن الملاك.', 'https://www.tanamiproperties.ae/Property-Management.aspx', 'تقدم تنامي العقارية خدمات إدارة العقارات تشمل فحص المستأجرين والتسويق والتحصيل والصيانة والتجديد وفق أنظمة الإيجار والتقارير الدورية للملاك. تذكر الشركة أنها تدير أكثر من 900 وحدة في 4 أبراج بدبي و3 بالشارقة وبرج في عجمان.', 'https://www.tanamiproperties.ae/Content/images/logo.webp', 'info@tanamiproperties.ae', 'مكتب 3405، مارينا بلازا، شارع المرسى، دبي مارينا، دبي', null, array['فحص المستأجرين', 'تحصيل الإيجار', 'تنسيق الصيانة', 'تجديد العقود', 'تقارير دورية للملاك']::text[], 'يضم فريق تأجير يشمل وسطاء مرخصين من دائرة الأراضي في دبي.', true
where not exists (select 1 from public.service_providers where category = 'property_mgmt' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Tanami Properties'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'property_mgmt', 'Deyaar Property Management', 'Deyaar Property Management', 'دبي', 'البرشاء 1', '+971 4 384 0950', 'https://www.deyaar.ae', null, 'ذراع إدارة العقارات لدى ديار تدير مشاريع سكنية وتجارية ومختلطة في الإمارات.', 'https://www.deyaar.ae/en/pm/', 'تقدم ديار لإدارة العقارات خدمات إدارة للمشاريع السكنية والتجارية والمختلطة في الإمارات، ولها فروع في أبوظبي والعين والشارقة والفجيرة ورأس الخيمة. تذكر الشركة أنها تدير أكثر من 12,000 وحدة وأكثر من 700 مشروع لأكثر من 400 مالك.', 'https://www.deyaar.ae/wp-content/uploads/2023/07/Logo_black.svg', 'contactus@deyaar.ae', 'الطابق الخامس، مبنى ديار، البرشاء 1، دبي', null, array['برج العامري - دبي', 'برج الفجيرة - الفجيرة', 'برج السادة - الشارقة']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'property_mgmt' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Deyaar Property Management'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'property_mgmt', 'Provis', 'Provis', 'أبوظبي', null, '+971 600 505056', 'https://www.provis.ae', null, 'شركة إدارة عقارات تابعة لمجموعة الدار تقدم إدارة العقارات والتأجير وإدارة جمعيات الملاك.', 'https://gulfnews.com/business/property/aldar-sets-up-company-to-handle-property-management-services-1.62303304', 'أسستها الدار العقارية كجهة مستقلة لإدارة العقارات وإدارة جمعيات الملاك وبيع وتأجير العقارات السكنية والتجارية. أعلنت عام 2019 إدارة نحو 13,500 وحدة ضمن محفظة إدارة العقارات، وفازت بعقود إدارة أكثر من 30 موقعًا في أبوظبي.', null, null, null, null, array['الزينة', 'المنيرة', 'البندر', 'أبراج صن وسكاي', 'البوابة والقوس']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'property_mgmt' and emirate = 'أبوظبي' and lower(coalesce(name_en, name_ar)) = lower('Provis'));
