select 'property_mgmt', 'Island Falcon Property Management', 'Island Falcon Property Management', 'أبوظبي', 'الخالدية', '+971 2 622 9974', 'https://www.ifpm.ae', 2008, 'شركة إدارة عقارات مقرها أبوظبي تقدم التأجير وتحصيل الإيجار والصيانة للملاك.', 'https://www.ifpm.ae/contact/', 'تأسست الشركة عام 2008 وتقدم إدارة العقارات وإدارة المرافق والتأجير وإدارة عقود الإيجار والصيانة والتسويق وتحصيل الإيجار وتسليم المفاتيح والإرشاد القانوني. لها مكاتب في أبوظبي ودبي وعجمان.', 'https://www.ifpm.ae/wp-content/uploads/2023/07/IFPM-black-logo.webp', 'info@ifpm.ae', 'مكتب 305، برج المنتزه، الخالدية، أبوظبي', 'https://goo.gl/maps/MPF8DPtSxZe3qe4i9', array['إدارة العقارات', 'تحصيل الإيجار', 'صيانة وإصلاح العقارات', 'إدارة العقارات التجارية', 'تسليم المفاتيح']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'property_mgmt' and emirate = 'أبوظبي' and lower(coalesce(name_en, name_ar)) = lower('Island Falcon Property Management'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'property_mgmt', 'Island Falcon Property Management - Ajman Office', 'Island Falcon Property Management - Ajman Office', 'عجمان', 'الراشدية 1', '+971 6 749 0300', 'https://www.ifpm.ae', 2008, 'مكتب عجمان لشركة آيلاند فالكون لإدارة العقارات للتأجير وتحصيل الإيجار والصيانة.', 'https://www.ifpm.ae/contact/', 'تأسست الشركة عام 2008 وتقدم إدارة العقارات والتأجير وتحصيل الإيجار والصيانة للملاك. يقع مقرها الرئيسي في أبوظبي ولها مكتبان في دبي وعجمان.', 'https://www.ifpm.ae/wp-content/uploads/2023/07/IFPM-black-logo.webp', 'info@ifpm.ae', 'مكتب 116، ذا بلاك رمادا سكوير، الراشدية 1، عجمان', 'https://goo.gl/maps/FfnrLUC5aXv9aGTC8', array['إدارة العقارات', 'تحصيل الإيجار', 'صيانة العقارات']::text[], null, true
