insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'property_mgmt', 'شركة السوم العقارية ذ.م.م', 'Alsoum Real Estate', 'الشارقة', 'السور', '+971 6 544 5569', 'https://www.alsoum.com', 2005, 'شركة عقارية في الشارقة تقدم إدارة العقارات والصيانة وإدارة الحسابات والخدمات القانونية الإيجارية.', 'https://www.alsoum.com/ar/', 'تأسست شركة السوم العقارية عام 2005 في الشارقة. تقدم إدارة العقارات والصيانة والسلامة والخدمات القانونية لنزاعات الإيجار وإدارة الحسابات والإشراف على المشاريع والوساطة والتقييم العقاري.', 'https://www.alsoum.com/ar/assets/img/img/logo.webp', 'info@alsoum.com', 'الشارقة – السور – بناء AMD – مكتب رقم M02 وM03 وM04', null, array['إدارة العقارات', 'الصيانة والسلامة', 'الخدمات القانونية لنزاعات الإيجار', 'إدارة الحسابات', 'التقييم العقاري']::text[], 'لديها أقسام مختصة للتأجير والحسابات والشؤون القانونية والتقييم والصيانة.', true
where not exists (select 1 from public.service_providers where category = 'property_mgmt' and emirate = 'الشارقة' and lower(coalesce(name_en, name_ar)) = lower('Alsoum Real Estate'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'property_mgmt', 'Al Mawarid Real Estate & Investments', 'Al Mawarid Real Estate & Investments', 'الشارقة', 'المجاز 3', '+971 6 556 6000', 'https://almawaridrealestate.ae', 2004, 'شركة عقارية في الشارقة تدير وتؤجر شققًا ومساحات تجارية في أبراج بالمجاز والبحيرة.', 'https://almawaridrealestate.ae/en/aboutus', 'تأسست الموارد العقارية والاستثمار عام 2004 في الشارقة. تعمل في تأجير الشقق والمساحات التجارية وإدارة الوحدات في عدد من الأبراج.', 'https://almawaridrealestate.ae/images/logo_white.png', 'info@almawaridrealestate.ae', 'مكتب 308، برج الدرة، كورنيش البحيرة، المجاز 3، الشارقة', null, array['برج أم القرى', 'برج سحاب الإمارات', 'برج الدرة', 'برج شراع الإمارات', 'برج الموارد']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'property_mgmt' and emirate = 'الشارقة' and lower(coalesce(name_en, name_ar)) = lower('Al Mawarid Real Estate & Investments'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'property_mgmt', 'SBK Real Estate', 'SBK Real Estate', 'الشارقة', 'المجاز 3', '+971 6 530 3030', 'https://www.sbkrealestate.com', null, 'شركة عقارية تقدم إدارة العقارات الشاملة والإيجار الرئيسي للملاك، ولها مكتب في الشارقة.', 'https://www.sbkrealestate.com/contact/', 'تقدم SBK Real Estate خدمات إدارة العقارات الشاملة، وإدارة شاملة مع ضمان، والإيجار الرئيسي (Head Lease)، وخدمة التأجير نيابة عن المالك. لها مكتبان في دبي (الكرامة) والشارقة (المجاز).', null, 'customercare@sbkrealestate.com', 'ميزانين 02، برج البحيرة، شارع كورنيش البحيرة، المجاز 3، الشارقة', null, array['إدارة العقارات الشاملة', 'إدارة شاملة مع ضمان', 'الإيجار الرئيسي', 'التأجير نيابة عن المالك', 'برج كيو - الشارقة']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'property_mgmt' and emirate = 'الشارقة' and lower(coalesce(name_en, name_ar)) = lower('SBK Real Estate'));

-- إعادة تفعيل حماية الإغراق
do $$ begin
  if exists (select 1 from pg_trigger where tgname = 'aq_rate_limit_service_providers') then
    alter table public.service_providers enable trigger aq_rate_limit_service_providers;
  end if;
end $$;


-- للتأكد: عدد الشركات في كل قسم وإمارة
select category, emirate, count(*) from public.service_providers where is_active group by 1, 2 order by 1, 3 desc;
